import React, { useState } from "react";
import { createRoot } from "react-dom/client";
import { FaFacebook, FaInstagram, FaCommentDots, FaCreditCard, FaCopy, FaCheck } from "react-icons/fa";
import "./style.css";

const profile = {
  name: "Xuân Linh",
  username: "@xuanlinh",
  bio: "👇 Link của mình ở đây",
  avatar: "https://ui-avatars.com/api/?name=Xuan+Linh&background=111827&color=fff&size=256",
  facebook: "https://www.facebook.com/hong.ngoc.401379/",
  bank: {
    name: "MB Bank",
    owner: "DOAN XUAN LINH",
    account: "0766666270",
    qr: "data:image/jpeg;base64,"
  }
};

function App() {
  const [copied, setCopied] = useState(false);
  const [showBank, setShowBank] = useState(false);

  const copyAccount = async () => {
    await navigator.clipboard.writeText(profile.bank.account);
    setCopied(true);
    setTimeout(() => setCopied(false), 1800);
  };

  return (
    <main className="page">
      <div className="card">
        <div className="top">
          <img className="avatar" src={profile.avatar} alt="Avatar" />
          <h1>{profile.name}</h1>
          <p className="username">{profile.username}</p>
          <p className="bio">{profile.bio}</p>
        </div>

        <div className="links">
          <a className="link facebook" href={profile.facebook} target="_blank" rel="noreferrer">
            <FaFacebook size={22} />
            <span>Facebook</span>
          </a>

          <button className="link bank" onClick={() => setShowBank(!showBank)}>
            <FaCreditCard size={22} />
            <span>Ngân hàng / Chuyển khoản</span>
          </button>

          {showBank && (
            <section className="bank-box">
              <p className="label">THÔNG TIN NHẬN TIỀN</p>
              <div className="bank-info">
                <div><span>Ngân hàng</span><b>{profile.bank.name}</b></div>
                <div><span>Chủ tài khoản</span><b>{profile.bank.owner}</b></div>
                <div><span>Số tài khoản</span><b>{profile.bank.account}</b></div>
              </div>

              <img className="qr" src={profile.bank.qr} alt="QR ngân hàng" />

              <button className="copy-btn" onClick={copyAccount}>
                {copied ? <FaCheck size={18} /> : <FaCopy size={18} />}
                {copied ? "Đã sao chép" : "Sao chép số tài khoản"}
              </button>
            </section>
          )}

       
        </div>

        <footer>© 2026 {profile.name}</footer>
      </div>
    </main>
  );
}

createRoot(document.getElementById("root")).render(<App />);
